#include <cstddef>
#include <unordered_map>

struct Key { unsigned account; unsigned revision; };
struct Equal {
  bool operator()(const Key& a, const Key& b) const {
    return a.account == b.account;
  }
};
struct Hash {
  std::size_t operator()(const Key& k) const {
    return k.revision;
  }
};
using Index = std::unordered_map<Key, int, Hash, Equal>;
